/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --bg-dark: #1b1622;
  --card-bg: #272033;
  --wax-body: #f4d38c;
  --wax-shadow: #d4a754;
  --flame-outer: #ff5722;
  --flame-mid: #ffb300;
  --flame-inner: #fff9c4;
  --wick-color: #2d2621;
  --text-main: #f5f2eb;
  --text-muted: #9f96aa;
  --btn-light: #ff9800;
  --btn-light-hover: #fb8c00;
  --btn-blow: #455a64;
  --btn-blow-hover: #546e7a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 24px 16px;
}

.card-container {
  background-color: var(--card-bg);
  width: 100%;
  max-width: 420px;
  min-height: 520px;
  border-radius: 16px;
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.45);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #fff;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 4px;
}

.scene-stage {
  width: 100%;
  height: 220px;
  display: flex;
  justify-content: center;
  align-items: flex-end;
  padding-bottom: 12px;
  position: relative;
}

.candle-assembly {
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}

/* Flame Glow effect */
.flame-glow {
  position: absolute;
  top: -30px;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 179, 0, 0.35) 0%, rgba(255, 87, 34, 0.1) 50%, rgba(0, 0, 0, 0) 70%);
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.candle-assembly.lit .flame-glow {
  opacity: 1;
  animation: glowPulse 1.2s infinite alternate ease-in-out;
}

/* Pixel Flame constructed using CSS box-shadow */
.pixel-flame {
  width: 8px;
  height: 8px;
  background: var(--flame-inner);
  margin-bottom: 2px;
  position: relative;
  opacity: 0;
  transform-origin: bottom center;
  box-shadow:
    0 -8px 0 0 var(--flame-inner),
    -8px 0px 0 0 var(--flame-mid),
    8px 0px 0 0 var(--flame-mid),
    0 8px 0 0 var(--flame-outer),
    -8px 8px 0 0 var(--flame-outer),
    8px 8px 0 0 var(--flame-outer);
  transition: opacity 0.2s ease;
}

.candle-assembly.lit .pixel-flame {
  opacity: 1;
  animation: pixelFlicker 0.25s steps(2, start) infinite alternate;
}

/* Pixel Wick */
.pixel-wick {
  width: 4px;
  height: 10px;
  background-color: var(--wick-color);
  border-radius: 1px;
}

/* Shrinking Candle Body */
.candle-stick {
  width: 48px;
  background-color: var(--wax-body);
  border-radius: 4px 4px 0 0;
  position: relative;
  transition: height 0.25s linear;
  box-shadow: inset -6px 0 0 var(--wax-shadow);
  overflow: hidden;
}

.candle-highlight {
  position: absolute;
  left: 6px;
  top: 0;
  bottom: 0;
  width: 4px;
  background-color: rgba(255, 255, 255, 0.4);
}

.candle-wax-drips {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 8px;
  background: repeating-linear-gradient(
    90deg,
    var(--wax-body) 0px,
    var(--wax-body) 8px,
    var(--wax-shadow) 8px,
    var(--wax-shadow) 12px
  );
}

.candle-base {
  width: 80px;
  height: 10px;
  background-color: #3e334a;
  border-radius: 6px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5), inset 0 2px 0 rgba(255, 255, 255, 0.1);
}

.status-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 70px;
  margin-top: 16px;
}

.timer-display {
  font-size: 2.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 2px;
  color: #fff;
}

.status-text {
  font-size: 1.25rem;
  font-weight: 600;
  color: #ff6f61;
  margin-top: 4px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
}

.control-bar {
  width: 100%;
  display: flex;
  gap: 12px;
  margin-top: 24px;
}

.btn {
  flex: 1;
  padding: 12px 8px;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.08s ease, box-shadow 0.15s ease;
  outline-offset: 3px;
}

.btn:focus-visible {
  outline: 2px solid #ffb300;
}

.btn:active:not(:disabled) {
  transform: translateY(2px);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.btn-primary {
  background-color: var(--btn-light);
  color: #1b1622;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--btn-light-hover);
}

.btn-secondary {
  background-color: var(--btn-blow);
  color: #fff;
}

.btn-secondary:hover:not(:disabled) {
  background-color: var(--btn-blow-hover);
}

.btn-ghost {
  background-color: transparent;
  color: var(--text-muted);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.btn-ghost:hover:not(:disabled) {
  background-color: rgba(255, 255, 255, 0.08);
  color: #fff;
}

@keyframes pixelFlicker {
  0% {
    transform: scale(1) translateY(0);
    filter: brightness(1);
  }
  50% {
    transform: scale(1.08, 0.95) translateY(-1px);
    filter: brightness(1.2);
  }
  100% {
    transform: scale(0.95, 1.05) translateY(1px);
    filter: brightness(0.9);
  }
}

@keyframes glowPulse {
  0% {
    transform: scale(0.95);
    opacity: 0.6;
  }
  100% {
    transform: scale(1.08);
    opacity: 0.85;
  }
}

(function () {
  'use strict';

  const TOTAL_DURATION_SECONDS = 180; // 3 minutes
  const INITIAL_HEIGHT = 120;
  const MIN_HEIGHT = 12;

  let remainingSeconds = TOTAL_DURATION_SECONDS;
  let timerInterval = null;
  let isBurning = false;

  // DOM references
  const lightBtn = document.getElementById('lightBtn');
  const blowOutBtn = document.getElementById('blowOutBtn');
  const resetBtn = document.getElementById('resetBtn');
  const timerDisplay = document.getElementById('timerDisplay');
  const statusText = document.getElementById('statusText');
  const candleAssembly = document.getElementById('candleAssembly');
  const candleStick = document.getElementById('candleStick');

  function formatTime(totalSeconds) {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    const paddedSeconds = seconds < 10 ? '0' + seconds : String(seconds);
    return `${minutes}:${paddedSeconds}`;
  }

  function updateHeight() {
    const progress = remainingSeconds / TOTAL_DURATION_SECONDS;
    const calculatedHeight = MIN_HEIGHT + (INITIAL_HEIGHT - MIN_HEIGHT) * progress;
    candleStick.style.height = `${Math.round(calculatedHeight)}px`;
  }

  function updateUI() {
    timerDisplay.textContent = formatTime(remainingSeconds);
    updateHeight();

    if (remainingSeconds <= 0) {
      statusText.removeAttribute('hidden');
      timerDisplay.setAttribute('hidden', '');
      candleAssembly.classList.remove('lit');
      lightBtn.disabled = true;
      blowOutBtn.disabled = true;
    } else {
      statusText.setAttribute('hidden', '');
      timerDisplay.removeAttribute('hidden');
      lightBtn.disabled = isBurning;
      blowOutBtn.disabled = !isBurning;
    }
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
      updateUI();
      if (remainingSeconds <= 0) {
        pauseTimer();
      }
    } else {
      pauseTimer();
    }
  }

  function startTimer() {
    if (isBurning || remainingSeconds <= 0) return;
    isBurning = true;
    candleAssembly.classList.add('lit');
    updateUI();
    timerInterval = setInterval(tick, 1000);
  }

  function pauseTimer() {
    if (!isBurning) return;
    isBurning = false;
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    candleAssembly.classList.remove('lit');
    updateUI();
  }

  function resetTimer() {
    pauseTimer();
    remainingSeconds = TOTAL_DURATION_SECONDS;
    candleStick.style.height = `${INITIAL_HEIGHT}px`;
    statusText.setAttribute('hidden', '');
    timerDisplay.removeAttribute('hidden');
    updateUI();
  }

  // Event Listeners
  lightBtn.addEventListener('click', startTimer);
  blowOutBtn.addEventListener('click', pauseTimer);
  resetBtn.addEventListener('click', resetTimer);

  // Keyboard Accessibility: Space/Enter trigger buttons natively; hotkeys 'L' and 'B'
  window.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
    if (e.key === 'l' || e.key === 'L') {
      if (!lightBtn.disabled) startTimer();
    } else if (e.key === 'b' || e.key === 'B') {
      if (!blowOutBtn.disabled) pauseTimer();
    } else if (e.key === 'r' || e.key === 'R') {
      resetTimer();
    }
  });

  // Initial render
  updateUI();
})();
